INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6933, NULL, NULL, 1284, 'Lollipop Chainsaw', 'Lollipop Chainsaw', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3kr3.jpg', NULL, 'Lollipop Chainsaw is the ''un-deadly'' story of sweet and killer zombie hunter Juliet Starling and her quest to uncover the root of a colossal zombie outbreak. With her wickedly awesome chainsaw in hand, Juliet slices, dices and splits her way through hordes of the undead, but soon realizes the horde is only the opening act to a festival of zombie rock lords determined to kill the chainsaw wielding cheerleader.', 'https://www.igdb.com/games/lollipop-chainsaw', '["PlayStation 3", "Xbox 360"]', NULL, NULL, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6934, NULL, NULL, 5086, 'Onechanbara: Bikini Samurai Squad', 'Onechanbara: Bikini Samurai Squad', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7npg.jpg', NULL, 'Play with a friend in co-op mode or switch between any of the three beautiful playable characters in single-player in Onechanbara: Bikini Samurai Squad. Each character has a variety of unique moves to master during combat to destroy enemy zombies. Get blood on either sister to trigger Rage Mode and gain more power and agility to destroy enemies faster and deadlier. For an added experience, go to Marketplace to download additional outfits and sword-flinging girls.', 'https://www.igdb.com/games/onechanbara-bikini-samurai-squad', '["Xbox 360"]', NULL, NULL, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6935, 119051, 'tt13443470', NULL, 'Wednesday', 'Wednesday', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/9PFonBhy4cQy7Jz20NpMygczOkv.jpg', 'https://image.tmdb.org/t/p/original/iHSwvRVsRyxpX7FE7GbviaDvgGZ.jpg', 'Smart, sarcastic and a little dead inside, Wednesday Addams investigates twisted mysteries while making new friends — and foes — at Nevermore Academy.', NULL, NULL, 55.1411, 8.338, 0, 1.0, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6936, 10069, 'tt0441796', NULL, 'Stay Alive', 'Stay Alive', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/hsSJwroE7jugEROB8tmyxJP91Ho.jpg', 'https://image.tmdb.org/t/p/original/hoGR8l7VYUqtUGDR65citqrhUqi.jpg', 'After the brutal death of a friend, a group of friends find themselves in possession of a video-game called "Stay Alive," a blood-curdling true story of a 17th century noblewoman known as the Blood Countess. After playing the game when they know they shouldn''t, however, the friends realize that once they die in the game — they die for real!', NULL, NULL, 2.619, 5.837, 0, 1.04, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
