INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6938, 59429, 'tt1728179', NULL, 'Paranormal Activity: Tokyo Night', 'パラノーマル・アクティビティ 第2章 TOKYO NIGHT', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/mh7j7XlYWo82UnQGhsxcuyolzp.jpg', 'https://image.tmdb.org/t/p/original/1S6HTRZ8HwuIM8KVNOaycN5WxwX.jpg', 'Koichi takes care of his sister, who has recently returned from a trip abroad in the United States as she is not well. While caring for her, he records evidence of ghosts in their home.', NULL, NULL, 2.15, 5.981, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6939, 827180, NULL, NULL, 'Ascetic', 'Ascetic', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/htHrcpwhy4MpBOFXsDJUZaphJwL.jpg', 'https://image.tmdb.org/t/p/original/pGO48tgou6EmuaqiFXXMPnkzvRH.jpg', 'A monk''s dedication is put to the ultimate test in this psychotically psychedelic animated nightmare. Will he succeed? Or will he fall victim to the ultimate enemy - his own self?', NULL, NULL, 0.4492, 10.0, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6940, 606041, 'tt10417938', NULL, 'The Scuzzies', 'The Scuzzies', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/q4GaV4mPSid3EL09TEHsGcaKC9D.jpg', 'https://image.tmdb.org/t/p/original/imTho201kYAeNImkRBN2FG6TpDT.jpg', '"The Scuzzies" is like a Saturday Morning Cartoon made for misanthropic hippy kids that like to mix tidepod colored mushrooms and goats blood into their sugary breakfast cereals.', NULL, NULL, 0.3768, 7.2, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6941, 1689213, 'tt9868848', NULL, 'Alice in Cyberland', 'Alice in Cyberland', 'movie', NULL, NULL, NULL, 'When criminal Cybernackists appear in the Cyberland, the vast 21st-century computer networks, Alice, Miss Catnick, Leina, and Julie are drawn in by the mysterious Lucia to become a fighting force of young girl soldiers in the Cyberland to combat the criminal element.', NULL, NULL, 0.172, 0.0, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6942, 466523, 'tt1712127', NULL, 'Malice in Wonderland: The Dolls Movie', 'Malice in Wonderland: The Dolls Movie', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/fi89eoCkEZ4RxjCRwK8IpntJbFW.jpg', NULL, 'This bawdy comedic film parodies the classics Alice in Wonderland, Wizard of Oz and Mommie Dearest. In the grand tradition of Shakespeare, all the roles are played by men (except two). The story opens with the hiring of a Joan Crawford look-a-like from Nanny Dearest, Incorporated. The relationship turns comedic tables with the cigarette smoking Alice in service to the demanding nanny. In a fit, ''Nanny Dearest'' flushes Alice and her rabbit down the toilet. Alice is deposited in Wonderland, where she meets a multitude of strange characters while pursuing the rabbit; ending at the Red Queen''s Orgy. Alice barely makes it out of Wonderland with her head. Awakening in bed with Nanny Dearest at her side, Alice realizes she has learned much from Nanny.', NULL, NULL, 0.3372, 1.0, 0, 2.035, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6943, 33322, 'tt0109151', NULL, 'Armitage III: Poly Matrix', 'アミテージ・ザ・サード POLY-MATRIX', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/7sUCRdjGe7VggDCGIHywfguYdAK.jpg', 'https://image.tmdb.org/t/p/original/sxuGFodklW2heRH5lx6AlP0R75E.jpg', 'Ross Sylibus is assigned to a police unit on a Martian colony, to find that women are being murdered by a psychotic named D''anclaude. He is assigned a very unorthodox partner named Naomi Armitage, who seems to have links to the victims. To stir things up more, every victim is found to be an illegally made third-generation android.', NULL, NULL, 2.1733, 6.458, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6944, 42882, 'tt0088863', NULL, 'Bubblegum Crisis', 'バブルガムクライシス', 'tv', 1987, 'https://image.tmdb.org/t/p/w500/rnF1zD3GP3L4DDoLIshUEH0JYHJ.jpg', 'https://image.tmdb.org/t/p/original/6LrQ2hzUzbKT14G1rJB63fJdCAT.jpg', 'MegaTokyo 2033: Tokyo was left flattened as a result from a great earthquake.

A new city, MegaTokyo, was then recreated due in no small part from the aid of a multi-million dollar company, Genom Corp. Genom created and mass-produced biomechanical creatures called Boomers to aid in the restoration of MegaTokyo.

When the Boomers began to run out of control, the ADPolice at first tried to stop them, but they proved to be far more difficult to deal with than was first imagined.

Under the ever looming Boomer threat, a group of four girls from varying degrees of society banded together. Calling themselves The Knight Sabers, they were the only ones with enough firepower and resourcefullness to defend the fledgling MegaTokyo from Genom and it''s berserk Boomers.', NULL, NULL, 5.6041, 6.973, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6945, 1095, 'tt0346314', NULL, 'Ghost in the Shell: Stand Alone Complex', '攻殻機動隊 STAND ALONE COMPLEX', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/6UH2vJryPpQp38noqvchu3uEeqX.jpg', 'https://image.tmdb.org/t/p/original/2rvFW70UeOMCTXGmYHij1bwHCiu.jpg', 'In the future when technological enhancements and robotics are a way of life, Major Motoko Kusanagi and Section 9 take care of the jobs that are too difficult for the police. Section 9 employs hackers, sharpshooters, detectives and cyborgs all in an effort to thwart cyber criminals and their plans to attack the innocent.', NULL, NULL, 11.7475, 8.223, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6946, 97187, 'tt0220218', NULL, 'Cyber City Oedo 808', 'サイバーシティ OEDO 808', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/2mNmqEDz1mm93C8XjhqyzmuiNP2.jpg', 'https://image.tmdb.org/t/p/original/4mkJ0igC1ZmM6URdHKaOBu5fgkR.jpg', 'In the city of Oedo 2808a.d., three Cyber criminals are given two choices, to either rot in jail or to join a special force of the Cyber Police to get possibly one more chance at freedom ever again. For each criminal apprehended, and for each successful mission done, the state will agree to reduce their sentences. Lead by Hasegawa, the new recruits: Sengoku, Gogul, and Benton will bring some hard justice to Oedo and possibly taste freedom again.', NULL, NULL, 3.1227, 6.877, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6947, 119590, 'tt0160523', NULL, 'Megazone 23 Part III', 'メガゾーン23 PART III', 'tv', 1989, 'https://image.tmdb.org/t/p/w500/xDuIApsp946VbJZBM4jtlNfAaLz.jpg', 'https://image.tmdb.org/t/p/original/jgnv5xTnOZoJqGl0362Byl0RWer.jpg', 'Years after the events of Megazone 23 II, the only city on Earth is the supposedly idyllic Eden. There lives Eiji Takanaka, a B Level hacker who has just been accepted into EX, the organization that controls Eden. However, before his first day on the job, he becomes embroiled in a network war, a legendary figure named EVE, and a plot to re-inhabit the Earth.', NULL, NULL, 2.2825, 8.5, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6948, 120253, 'tt0158634', NULL, 'Genocyber', 'ジェノサイバー', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/7z24eVtTXogfiFdUoKhnZ2O9Q6Q.jpg', 'https://image.tmdb.org/t/p/original/jpN0SWrhcKUbkjiP1Rt2qPOdxO6.jpg', 'As the nations of the world begin to merge, world peace is threatened by the private armies of individual corporations. The Kuryu Group has just discovered a weapon that will tip world power in their favor. The Genocyber: a nightmarish combination of cybernetics and psychic potential. Many desire to control this monstrosity, but can its hatred be contained... Battle erupts, and the cyberpunk world of the future is about to explode with violence.', NULL, NULL, 0.5029, 5.6, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6949, 57224, 'tt0220333', NULL, 'Bio Hunter', 'バイオ・ハンター', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/tfjQGbYsHFq2TUrGGMJ4JU8snO9.jpg', 'https://image.tmdb.org/t/p/original/cL4HA8zHyRUZuMhA8wjL0uG4AJm.jpg', 'A strange virus known as the Demon Virus, attacks the human genetic code, transforming people into monsters with demonic powers. One particular monster is terrorizing the streets of Tokyo. ripping open young women to devour their livers. A famed psychic holds the secret to the identity and purpose of this monster. Now it is up to two molecular biologists. self-proclaimed Bio Hunters Komada and Koshigaya, to reach the psychic and his beautiful daughter before its too late! The Demon Virus is out to conquer the world.', NULL, NULL, 1.6921, 5.87, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6950, 80089, 'tt0376058', NULL, 'Parasite Dolls', 'パラサイトドールズ', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/bCDVdpjhqbfMsSg0TlNeGMdg2el.jpg', 'https://image.tmdb.org/t/p/original/6eHSovkwyVt5VI0xt6aCWimeYVh.jpg', 'Beauty is only skin deep, but when you can’t see beneath the skin, how can you know what you’re really dealing with? In a world where perfect androids called Boomers have infiltrated every aspect of society, it’s the job of Branch to maintain peace between the people and the plastic. Unfortunately, not all boomers are created perfect, and when boomers go bad, people die. The thin blue line that separates man from machine is about to meet its most horrifying test in Parasite Dolls.', NULL, NULL, 0.777, 5.695, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6951, 69326, 'tt1666700', NULL, 'Psycho Gothic Lolita', 'ゴスロリ処刑人', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/pIcpx9n3TmgyKNk3HdtwWbbTtuy.jpg', 'https://image.tmdb.org/t/p/original/6AvUyBEnKO24VPx5itYUz31ZuS1.jpg', 'Yuki lives at home in peace until one day a unit of assassins breaks in and kill her mother. In order to revenge herself Yuki becomes a demon of vengeance by donning gothic lolita clothing, using a parasol as a deadly weapon, and executing the guilty in God''s name.', NULL, NULL, 1.346, 5.16, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
