INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6959, 72351, 'tt0163450', NULL, 'Hilda Hurricane', 'Hilda Furacão', 'tv', 1998, 'https://image.tmdb.org/t/p/w500/xJgDZQDscZpQ5JJ2Ms9QOYoIEk9.jpg', 'https://image.tmdb.org/t/p/original/2kHhLv6RPZUbYcqk3L9RarOYzlA.jpg', 'After breaking off her engagement on her wedding day and going directly to a prostitution house, a young model becomes the city''s most famous harlot, known as "Hilda Hurricane", in the 50''s Brazil. She could do fine if it wasn''t for Malthus, a young novice said to be a saint, for whom she falls in love. However, the boy is kept under the strict, severe doctrine of Father Nelson, a conservative priest intolerant even to every minor sin. Things start getting harder when Roberto, Malthus'' old friend and a communist reporter (the actual author of the story), tries to interview Hilda and disclosure the real reasons behind her radical change of mind. In the meantime, the middle-classes are terrified by the "leftist threat" in Brazilian politics.', NULL, NULL, 21.671, 8.1, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6960, 91425, 'tt8146754', NULL, 'Infinity Train', 'Infinity Train', 'tv', 2019, 'https://image.tmdb.org/t/p/w500/wEhc48kGjoWw8qcHu2Lar7NFrgG.jpg', 'https://image.tmdb.org/t/p/original/xMFRoCMrpEeS5cl7gXpJqC4PhIN.jpg', 'Passengers on board the mysterious Infinity Train must explore a series of endless cars that each contain unique worlds and puzzles to solve in order to unravel the mysteries of the train - and within themselves - to open the doorway home.', NULL, NULL, 12.0189, 8.419, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6961, 10979, 'tt0063903', NULL, 'The Gnomes of Dulwich', 'The Gnomes of Dulwich', 'tv', 1969, NULL, NULL, 'The Gnomes of Dulwich was a United Kingdom television sitcom originally shown in six episodes from 12 May 1969 to 16 June 1969. Written by Jimmy Perry, the show starred Terry Scott, Hugh Lloyd, John Clive, Leon Thau, Anne de Vigier and Lynn Dalby as garden gnomes living at 25 Telegraph Road, Dulwich, London, England.

The title is a reference to the term "Gnomes of Zürich".

The tapes were wiped in the 1970s and no material seems to have survived.', NULL, NULL, 1.0076, 8.0, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6962, 34052, 'tt0074705', NULL, 'Jack and the Beanstalk', 'ジャックと豆の木', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/jJbWGUeVHxWdiQyzOSosCs9kdVQ.jpg', 'https://image.tmdb.org/t/p/original/sTVHLgs8QJFPhzgwtrFOZEeBpeX.jpg', 'An adventurous young boy named Jack climbs a giant beanstalk to a magical kingdom governed by a greedy, tyrannical giant.', NULL, NULL, 0.8031, 6.4, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6963, 20421, 'tt0102802', NULL, 'Rock-A-Doodle', 'Rock-A-Doodle', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/q5xSS8MNmrwR3em6VB6OC3992d6.jpg', 'https://image.tmdb.org/t/p/original/iUMbJTU1mdlHOLHB8d3JqAsWj2s.jpg', 'Chanticleer is a foolhardy farm rooster who believes his crows can actually make the sun come up and shine. When the sun rises one morning without Chanticleer''s crow, he leaves the farm in disgrace and runs off to become a rock ''n'' roll singer. But in his absence, a sinister, sunshine-hating owl prepares to take over.', NULL, NULL, 3.6422, 6.233, 0, 9.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6964, 36751, 'tt0086489', NULL, 'Twice Upon a Time', 'Twice Upon a Time', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/abx7BQF3O23LJGTDTmQQ0CTwc8c.jpg', 'https://image.tmdb.org/t/p/original/yS3AGFYDRAbqjvkVH00zQX8hWlf.jpg', 'In the world of the Murkworks where nightmares are made, the evil Synonamess Botch hatches a scheme to make non-stop nightmares. Only Ralph and Mumford, misfits from the cheery land of Frivoli where good dreams are made, can stop him.', NULL, NULL, 1.508, 6.63, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6965, 40611, 'tt0079474', NULL, 'The Lion, the Witch and the Wardrobe', 'The Lion, the Witch and the Wardrobe', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/5ebzw3VOkceR4gq9w3ZQ5nptOS4.jpg', 'https://image.tmdb.org/t/p/original/sNdTKQ1cTNmbTMmorpRDUkPqdsM.jpg', 'Four children pass through a mystic portal in a wardrobe and discover the magical kingdom of Narnia, a land of talking animals and mythical creatures. There, an evil witch''s spell has cast the land into eternal winter. Fearing that an ancient prophecy is coming to fruition, and that the children are Narnia''s rightful rulers, the White Witch tricks their youngest brother into betraying his family, enacting an ancient magic that she can use to halt the fulfillment of the prophecy. Now, only Aslan, noble lion and High King above all kings in Narnia, can help them defeat the witch, restore springtime to Narnia, and claim their rightful places on the throne.', NULL, NULL, 1.2581, 6.8, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6966, 34467, 'tt0078477', NULL, 'The Water Babies', 'The Water Babies', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/vpgFomQKyvpsxazK0SB5pB7S8xo.jpg', 'https://image.tmdb.org/t/p/original/wJmrzkRyOYwMed24E7QcwrLVFIF.jpg', 'Grimes, an amoral chimney sweep, occasionally likes to steal valuables from his clients. One day, on the verge of being caught, he frames his young apprentice, Tom, for the crime. Tom runs away and jumps into a river where, instead of drowning, he finds himself transformed into a mystical aquatic creature. Swimming and breathing effortlessly, he discovers a colorful underwater world replete with creatures both cruel and kind.', NULL, NULL, 1.2473, 6.25, 0, 8.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
