INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6972, 124618, 'tt0113233', NULL, 'Guimba the Tyrant', 'Guimba, un tyran une époque', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/d9uQAa2ueKLJU5Nqq7t0gi0ty4a.jpg', 'https://image.tmdb.org/t/p/original/k15DR1qt9djuUDygB9UYiVjxkNU.jpg', 'The movie shows the rise and fall of a cruel and despotic village chief Guimba, and his son Jangine in a fictional village in the Sahel of Mali.', NULL, NULL, 0.6321, 6.1, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6973, 13245, 'tt0285441', NULL, 'Atanarjuat: The Fast Runner', 'ᐊᑕᓈᕐᔪᐊᑦ', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/jSGiFOTwosoiAAXLTLHtzMUCVUN.jpg', 'https://image.tmdb.org/t/p/original/q3XAe77oga8zCH8G6d8T4izEPZ6.jpg', 'Based on a local legend and set in an unknown era, it deals with universal themes of love, possessiveness, family, jealousy and power. Beautifully shot, and acted by Inuit people, it portrays a time when people fought duels by taking turns to punch each other until one was unconscious, made love on the way to the caribou hunt, ate walrus meat and lit their igloos with seal-oil lamps.', NULL, NULL, 1.9513, 6.797, 0, 2.095, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6974, 355196, 'tt3278224', NULL, 'I Dream in Another Language', 'Sueño en otro idioma', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/tUEhleHFj47f84qd3tCrzQvLbpu.jpg', 'https://image.tmdb.org/t/p/original/2c7hnytwPd3stYJMmOEeekd72vV.jpg', 'An indigenous language is in peril, as its last two speakers had a quarrel in the past and haven''t spoken to each other in over 50 years. Martín, a young linguist, will undertake the challenge of bringing the old friends back together and convincing them to speak once again so he can obtain a recorded registration of the language and study it.', NULL, NULL, 1.4235, 7.86, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6975, 283322, 'tt3399916', NULL, 'The Dead Lands', 'The Dead Lands', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/wdlRuuA2CtS0KtaVzAikZxVHRIk.jpg', 'https://image.tmdb.org/t/p/original/zyoHNsjDWdSk1gsWHkihntOkIEb.jpg', 'Hongi, a Maori chieftain’s teenage son, must avenge his father’s murder in order to bring peace and honour to the souls of his loved ones after his tribe is slaughtered through an act of treachery. Vastly outnumbered by a band of villains led by Wirepa, Hongi’s only hope is to pass through the feared and forbidden “Dead Lands” and forge an uneasy alliance with a mysterious warrior, a ruthless fighter who has ruled the area for years.', NULL, NULL, 1.206, 6.1, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6976, 724495, 'tt8093700', NULL, 'The Woman King', 'The Woman King', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/438QXt1E3WJWb3PqNniK0tAE5c1.jpg', 'https://image.tmdb.org/t/p/original/p5kb4VwnK0bkxsOmME3SBKAcBoe.jpg', 'The story of the Agojie, the all-female unit of warriors who protected the African Kingdom of Dahomey in the 1800s with skills and a fierceness unlike anything the world has ever seen, and General Nanisca as she trains the next generation of recruits and readies them for battle against an enemy determined to destroy their way of life.', NULL, NULL, 9.8504, 7.574, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6977, 359151, 'tt4239726', NULL, 'Tanna', 'Tanna', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/iKk0Nu3dytbDzX1SFwYJvUreQW.jpg', 'https://image.tmdb.org/t/p/original/oKMLvGOlEl7BVRHHJxH7NE3W8gc.jpg', 'In a traditional tribal society in the South Pacific, a young girl, Wawa, falls in love with her chief’s grandson, Dain. When an inter-tribal war escalates, Wawa is unknowingly betrothed as part of a peace deal. The young lovers run away, refusing her arranged fate. They must choose between their hearts and the future of the tribe, while the villagers must wrestle with preserving their traditional culture and adapting it to the increasing outside demands for individual freedom.', NULL, NULL, 1.6028, 6.6, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6978, 40423, 'tt0053146', NULL, 'Black Orpheus', 'Orfeu Negro', 'movie', 1959, 'https://image.tmdb.org/t/p/w500/fJWzdNRnfjcJuaZiKqaSURFV6Lg.jpg', 'https://image.tmdb.org/t/p/original/mXHZJu6wmmNIhbidSMp24PQ3WNw.jpg', 'Young lovers Orfeu and Eurydice run through the favelas of Rio during Carnaval, on the lam from a hitman dressed like Death and Orfeu''s vengeful fiancée Mira and passing between moments of fantasy and stark reality. This impressionistic retelling of the Greek legend of Orpheus and Eurydice introduced bossa nova to the world with its soundtrack by young Brazilian composers Luiz Bonfá and Antonio Carlos Jobim.', NULL, NULL, 3.3962, 7.006, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6979, 482061, 'tt7670864', NULL, 'Balangiga: Howling Wilderness', 'Balangiga: Howling Wilderness', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/rAbLXYjtcRZqtsniMwU6mTNRA4s.jpg', 'https://image.tmdb.org/t/p/original/tieHEnvWwQpeTKnnYOiQa9bM2xK.jpg', '1901, Balangiga. Eight-year-old Kulas flees town with his grandfather and their carabao to escape General Smith''s Kill & Burn order. He finds a toddler amid a sea of corpses and together, the two boys struggle to survive the American occupation.', NULL, NULL, 0.6125, 9.0, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6980, 54927, 'tt0104255', NULL, 'The Feast of the Chicken', 'Das Fest des Huhnes', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/lz2f7C9URXsEegW4AwrBK3bYhxe.jpg', 'https://image.tmdb.org/t/p/original/AkGFWv8Ua7pvphYcyw9cv51Y1dK.jpg', 'The morals and customs of the "native peoples" of Upper Austria are described by a team of anthropologists from Sub-Saharan Africa in the style of European and American anthropologists in the non-western world. While making the film, they discover new cultural phenomena. Wippersberg turns around the research methodology of Western anthropologists of performing ethnologic studies, and then popularising them by means of a documentary film.', NULL, NULL, 1.3487, 7.591, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
