INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6982, 618208, 'tt10849514', NULL, 'This Is Not a Burial, It''s a Resurrection', 'This Is Not a Burial, It''s a Resurrection', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/9crWLzqUrFEoJHj8kbrUaRulKM.jpg', 'https://image.tmdb.org/t/p/original/oTriUKBP348iFQ6wHAoxL2A4HcQ.jpg', 'Amongst the mountains of Lesotho, an 80-year-old widow winds up her affairs and makes arrangements for her burial. But when her village is threatened with resettlement due to the construction of a reservoir, she finds a new will to live and ignites a spirit of resistance within her community.', NULL, NULL, 1.3101, 7.5, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
