INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6989, 95631, 'tt12285778', NULL, 'Super Cub', 'スーパーカブ', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/pcJLrikS9bsYsKn6U0ttx4NmJcP.jpg', 'https://image.tmdb.org/t/p/original/owvL8PxjIvU4X83mJ4Z7aYMVBmw.jpg', 'Koguma is a high school girl in Yamanashi. She has no parents, friends, or hobbies, and her daily life is empty. One day, Koguma gets a used Honda Super Cub motorcycle. This is her first time going to school on a motorcycle. Running out of gas and hitting detours become a small source of adventure in Koguma''s life. She is satisfied with this strange transformation, but her classmate Reiko ends up talking to her about how she also goes to school by motorcycle. One Super Cub begins to open up a lonely girl''s world, introducing her to a new everyday life and friendship.', NULL, NULL, 4.8417, 7.316, 0, 6.52, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
