INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7005, 57829, 'tt1324055', NULL, 'The Mill and the Cross', 'Młyn i krzyż', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/3IKLkxxXf38C2hY9ONi6Lvlz1qM.jpg', 'https://image.tmdb.org/t/p/original/osjuwnDnIGW0MpHJgcSRBUjPsZ6.jpg', 'What would it be like to step inside a great work of art, have it come alive around you, and even observe the artist as he sketches the very reality you are experiencing? From Lech Majewski, one of Poland''s most acclaimed filmmakers, The Mill and the Cross is a cinematic re-staging of Pieter Bruegel''s masterpiece "Procession to Calvary," presented alongside the story of its creation.', NULL, NULL, 1.4734, 6.353, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
