INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7013, 11, 'tt0076759', NULL, 'Star Wars', 'Star Wars', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', 'https://image.tmdb.org/t/p/original/yUiXA68FfQeA8cRBhd0Ao0jIRZt.jpg', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', NULL, NULL, 44.3392, 8.206, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7014, 568467, 'tt7983894', NULL, 'Ammonite', 'Ammonite', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/5lx4pUHWZoOKJWsVsvurRRNW9FK.jpg', 'https://image.tmdb.org/t/p/original/23wCZgZ3mDtATocmy1lXNLM7pyx.jpg', 'In 1840s England, palaeontologist Mary Anning and a young woman sent by her husband to convalesce by the sea develop an intense relationship. Despite the chasm between their social spheres and personalities, Mary and Charlotte discover they can each offer what the other has been searching for: the realisation that they are not alone. It is the beginning of a passionate and all-consuming love affair that will defy all social bounds and alter the course of both lives irrevocably.', NULL, NULL, 5.1544, 6.899, 0, 3.09666666666666667e+00, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7015, 37041, 'tt0040000', NULL, 'The Woman on the Beach', 'The Woman on the Beach', 'movie', 1947, 'https://image.tmdb.org/t/p/w500/fz7ASNtc7koTdrx4fuRZbLobgSw.jpg', 'https://image.tmdb.org/t/p/original/2sRTQTtY5lSRqG9njDoYTUWPVvv.jpg', 'A sailor suffering from post-traumatic stress becomes involved with a beautiful and enigmatic seductress married to a blind painter.', NULL, NULL, 1.2106, 6.167, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7016, 568119, NULL, NULL, 'A Stolen Life', 'A Stolen Life', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/lOW2SDQ84c7KCgDoqzRhXEVJwDz.jpg', NULL, 'Based on a true story. Flashbacks into the past. Mrs Chen is facing labor difficulties while giving birth to her twin daughter. However, these pair of twins had been diagnosed as dead by the doctor months ago. This kept Old Mrs Chen suspicious on whether her son, Mr Chen did something to bring the lives back. Chen Mo grew up normally in the family, but constantly has visuals of another twin sister in her mind. Chen Mo’s boyfriend, Ao Yang proposes to her but he realizes that she does not seem very happy and there are many secrets untold…', NULL, NULL, 0.8377, 0.0, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7017, 1959, 'tt0120257', NULL, 'Swept from the Sea', 'Swept from the Sea', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/w5Or62J6mF099MQcn0Cq8ycIfqB.jpg', 'https://image.tmdb.org/t/p/original/2xEzike2hCWfkAlj4HTRPvkeVo8.jpg', 'The film tells the story of Russian emigree and the only survivor from ship crash Yanko Goorall and servant Amy Foster in the end of 19th century. When Yanko enters a farm sick and hungry after the shipwreck, everyone is afraid of him, except for Amy, who is very kind and helps him. Soon he becomes like a son for Dr. James Kennedy and romance between Yanko and Amy follows.', NULL, NULL, 1.3774, 6.422, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7018, 61245, 'tt3098842', NULL, 'Jamaica Inn', 'Jamaica Inn', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/3SZ2TSpaVIRJG8FNDsX7HLZlE5q.jpg', 'https://image.tmdb.org/t/p/original/rV1c8abChfUaZEmS0LCLRE9zTvG.jpg', 'Set in 1820 against the forbidding backdrop of windswept Cornish moors, the story follows the journey of young and spirited Mary who is forced to live with her Aunt Patience after the death of her mother. Mary arrives at the isolated Jamaica Inn to discover her Aunt is a shell of the carefree woman she remembers from her childhood, and instead finds a drudge who is firmly under the spell of her domineering husband Joss. The Inn has no guests - the rooms are locked and kept for storage - but it soon becomes clear that it’s a cover, as Joss is the leader of a smuggling ring, and Jamaica Inn the hub of his ‘free’ trade.', NULL, NULL, 2.8353, 6.5, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7019, 394269, 'tt5662106', NULL, 'Lemonade', 'Lemonade', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/x6sBCNHyjrCVF5Pa3Oa8GCP58UU.jpg', 'https://image.tmdb.org/t/p/original/wLiJKxvEVNgtHT0OrHbiz6Uhu4J.jpg', 'The second "visual album" (a collection of short films) by Beyoncé, this time around she takes a piercing look at racial issues and feminist concepts through a sexualized, satirical, and solemn tone.', NULL, NULL, 1.1979, 8.43, 0, 1.0, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
