INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7021, 41820, 'tt0240980', NULL, 'Till Human Voices Wake Us', 'Till Human Voices Wake Us', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/hVUYqZ2sGjEOYXA0tumra96ZxJI.jpg', 'https://image.tmdb.org/t/p/original/yLBoS1Gtmz7acpW12we7GfyrfZQ.jpg', 'Sam and Silvy are best friends. One night, as they are watching a falling star while floating on their backs in a lake, Sylvy disappears from his side. Despite his best efforts, he cannot find her under water. Many years later, Sam, now a psychologist, returns to bury his father. Back in his hometown, he meets a woman called Ruby who reminds him in so many ways of his lost love.', NULL, NULL, 1.1598, 5.259, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7022, 954513, NULL, NULL, 'Henze: Ondine', 'Henze: Ondine', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/c32YkbTraK64DNOKTxEGjjBSnHO.jpg', 'https://image.tmdb.org/t/p/original/44N3wbX76lxAaQbpuO1pnCJkWWa.jpg', '‘Ondine’, a ballet by Frederick Ashton, premiered at the Royal Opera House, Covent Garden, on 27 October 1958, with Margot Fonteyn in the title role of the water nymph. In this 2009 revival (27 May 2009 to 8 June 2009) at the Royal Opera House, Covent Garden, in London, the role of Ondine is performed by Miyako Yoshida, in the spellbinding underwater world of Ondine, staged by the Royal Ballet. Frederick Ashton’s shimmering choreography, Lila de Nobili’s impressionistic sets and Hans Werner Henze’s vibrant and inventive score, composed especially for the occasion, combine in an unforgettable way to evoke the myriad moods and colours of the sea.', NULL, NULL, 1.2619, 0.0, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
