INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7025, 271796, 'tt0374083', NULL, 'The Murmuring', '낮은 목소리 - 아시아에서 여성으로 산다는 것', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/rIP2OEmgpz3OdYqyj4L2U64ntF2.jpg', 'https://image.tmdb.org/t/p/original/7XtSa1GTlbcqSMpNAIfJzK5nHsY.jpg', 'Every Wednesday at noon, women who were kidnapped for sexual purpose by the Japanese army during its imperialism and their supporters demonstrate against Japanese government to request official apology and indemnity for their crimes. This documentary portrays sexually abused old women''s suppressed story of overcoming of their shame and forced silence.', NULL, NULL, 0.5575, 5.8, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
