INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7085, 83389, 'tt1798188', NULL, 'From Up on Poppy Hill', 'コクリコ坂から', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/rRLYX4RZIyloHSJwvZKAhphAjiB.jpg', 'https://image.tmdb.org/t/p/original/v3bVN8SjeA9O0nUBtMfRcE0fJpR.jpg', 'Yokohama, 1963. Japan is picking itself up from the devastation of World War II and preparing to host the 1964 Olympics—and the mood is one of both optimism and conflict as the young generation struggles to throw off the shackles of a troubled past. Against this backdrop of hope and change, a friendship begins to blossom between high school students Umi and Shun—but a buried secret from their past emerges to cast a shadow on the future and pull them apart.', NULL, NULL, 6.4402, 7.527, 0, 9.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
