INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7109, 617505, 'tt10682266', NULL, 'Hubie Halloween', 'Hubie Halloween', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/dbhC6qRydXyRmpUdcl9bL9rARya.jpg', 'https://image.tmdb.org/t/p/original/aOeshAxAhiDVIiHsXVFmF6bgclh.jpg', 'Hubie Dubois, despite his devotion to his hometown of Salem, Massachusetts (and its legendary Halloween celebration), is a figure of mockery for kids and adults alike. But this year, something really is going bump in the night, and it’s up to Hubie to save Halloween.', NULL, NULL, 3.6414, 5.886, 0, 2.8, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7110, 103663, 'tt2106476', NULL, 'The Hunt', 'Jagten', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/jkixsXzRh28q3PCqFoWcf7unghT.jpg', 'https://image.tmdb.org/t/p/original/jmVWlCZ8hRtmrQGbKXXFHsrSohp.jpg', 'A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.', NULL, NULL, 10.7616, 8.092, 0, 1.24, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7111, 631049, 'tt10887504', NULL, 'Love, Fall & Order', 'Love, Fall & Order', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/kM8ZCOHDvRE8Qs499w0tfP06t0a.jpg', 'https://image.tmdb.org/t/p/original/qYckYSDHjLjdINCpXimlEqhlhhz.jpg', 'When Claire goes home to save her dad''s annual Fall Fest on her family''s pumpkin farm, sparks fly with an old rival – the opposing lawyer she now faces in court.', NULL, NULL, 2.1512, 6.48, 0, 1.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7112, 1330439, 'tt37580160', NULL, 'The Spirit of Halloweentown', 'The Spirit of Halloweentown', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/uDsOi9tYaTB2bh1xMqgQ2Md7224.jpg', 'https://image.tmdb.org/t/p/original/vB1tFSQ7pK1Nzuv3ILZXnrOgt2.jpg', 'What kind of people live in a town that revolves around Halloween? In Oregon, the picturesque town of St. Helens was home to the filming of the Disney Channel’s youthful horror-lite film HALLOWEENTOWN in the 1990s. After it became a surprise hit—and now a cult classic—the town decided to capitalize on this starring role and invites tourists to celebrate the film and Halloween with them every year.', NULL, NULL, 0.2232, 0.0, 0, 1.28, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7113, 1180326, 'tt11333048', NULL, 'The Night of the Harvest', 'The Night of the Harvest', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/3eqgVMbnIxQZwpTt21GRBGWbAFA.jpg', 'https://image.tmdb.org/t/p/original/r9EPByteMuiJkFpLBguDjiyKelX.jpg', 'Two people are murdered and several others mysteriously disappear one night. Five months later, Aubrey and her friends go geocaching behind an old cornfield where they are stranded and stalked by a masked woman in white.', NULL, NULL, 0.6742, 0.0, 0, 1.28, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7114, 11361, 'tt0097474', NULL, 'Halloween 5: The Revenge of Michael Myers', 'Halloween 5: The Revenge of Michael Myers', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/rYvP6yMXCIVHnkVtwGaAXFmpzkB.jpg', 'https://image.tmdb.org/t/p/original/AbxX6yknCzrS2Uu67IN4HVbqKez.jpg', 'After lying in a coma for a year, Michael Myers awakens and stalks his way back to his small hometown in Illinois, intent on killing his niece, Jamie, who has been confined to a mental institution since his last attempt to slay her.', NULL, NULL, 3.4791, 5.3, 0, 1.28, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7115, 27646, 'tt1268809', NULL, 'Night of the Demons', 'Night of the Demons', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/zm6pIvRM91rtJgQb3BlUczLr4qd.jpg', 'https://image.tmdb.org/t/p/original/ol2FlTsW52tBqIGLBlFH3R0O1sg.jpg', 'Angela is throwing a decadent Halloween party at New Orleans'' infamous Broussard Mansion. But after the police break up the festivities, Maddie and a few friends stay behind. Trapped inside the locked mansion gates, the remaining guests uncover a horrifying secret and soon fall victim to seven vicious, blood-thirsty demons.', NULL, NULL, 1.8155, 5.1, 0, 1.28, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7116, 5055, 'tt0052080', NULL, 'Ashes and Diamonds', 'Popiół i diament', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/nE8aqRvVnRQEqskiarnFhdJdk8g.jpg', 'https://image.tmdb.org/t/p/original/1QlZ3Kge4bCH01V3VibxckeVIiu.jpg', 'A young academy soldier, Maciek Chelmicki, is ordered to shoot the secretary of the KW PPR. A coincidence causes him to kill someone else. Meeting face to face with his victim, he gets a shock. He faces the necessity of repeating the assassination.  He meets Krystyna, a girl working as a barmaid in the restaurant of the "Monopol" hotel. His affection for her makes him even more aware of the senselessness of killing at the end of the war. Loyalty to the oath he took, and thus the obligation to obey the order, tips the scales.', NULL, NULL, 1.9529, 7.412, 0, 2.045, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7117, 43322, 'tt0048500', NULL, 'A Generation', 'Pokolenie', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/zUQKN61bjCxSgubchybgzExMCNR.jpg', 'https://image.tmdb.org/t/p/original/mVQthfjH5QrkDyiY6RxAgl60LqG.jpg', 'Stach is a wayward teen living in squalor on the outskirts of Nazi-occupied Warsaw. Guided by an avuncular Communist organizer, he is introduced to the underground resistance—and to the beautiful Dorota. Soon he is engaged in dangerous efforts to fight oppression and indignity, maturing as he assumes responsibility for others’ lives.', NULL, NULL, 1.559, 6.968, 0, 1.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7118, 29933, 'tt0050585', NULL, 'Kanal', 'Kanał', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/mUxZNNmvX3MwIJ9LTcuw76ZdtN6.jpg', 'https://image.tmdb.org/t/p/original/kfuJtNiY3aevZHzSMA007pbVWqH.jpg', 'In the last few days of the Warsaw Uprising during World War II, a modest group of Resistance members remains. The band must take refuge in the sewers under the orders of leader Zadra, but it''s only a matter of time before they will have to emerge. However, when they try, they are met only with intense hostility from the Nazis. Despite their attempts stay resolute through immense mental strain, it becomes increasingly apparent that they may be doomed.', NULL, NULL, 1.2421, 7.7, 0, 3.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7119, 13813, 'tt1034303', NULL, 'Defiance', 'Defiance', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/kEF847cC9yAkgoeEZPQwnF08p6p.jpg', 'https://image.tmdb.org/t/p/original/cwVwPnsMHrgfM0dkpAJIeU4YEQN.jpg', 'Based on a true story, during World War II, four Jewish brothers escape their Nazi-occupied homeland of West Belarus in Poland and join the Soviet partisans to combat the Nazis. The brothers begin the rescue of roughly 1,200 Jews still trapped in the ghettos of Poland.', NULL, NULL, 4.3527, 6.845, 0, 2.075, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7120, 293982, 'tt3765326', NULL, 'Warsaw 44', 'Miasto 44', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/k9WOOkVur2Gwo93wuiKzJDm2mUK.jpg', 'https://image.tmdb.org/t/p/original/r3nuY1fTkjqKxaUYjJi4OThoXJx.jpg', 'City of Warsaw, Poland, August 1st, 1944. Citizens have experienced inhuman acts of terror and violence during five long years of Nazi occupation. As the Soviet Army relentlessly approaches, the youngest and bravest among them rise up as one and face tyranny fighting street by street, but the price to pay will be high and hard the way to freedom…', NULL, NULL, 10.9284, 6.666, 0, 2.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7121, 9075, 'tt0389557', NULL, 'Black Book', 'Zwartboek', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/vZaYDWa3IqTNKsHCsUr72J4zTJ6.jpg', 'https://image.tmdb.org/t/p/original/vT39NcxIWHL5XVNQGRMbS8NxXs0.jpg', 'Israel, 1956: Jewish teacher Rachel Stein rather unexpectedly meets an old friend at the kibbutz. It brings back memories of her experiences in the Netherlands during the war, memories of betrayal. In September 1944, Rachel''s hiding place is bombed by Allied troops; she makes contact with a resistance member and joins a group of Jews to be smuggled across the Biesbosch to the freed South Netherlands. Only Rachel escapes a massacre by patrol Germans, and is rescued by a resistance group under the leadership of Gerben Kuipers, whose son is captured trying to smuggle weapons. Kuipers asks Rachel to seduce SS-hauptsturmführer Ludwig Müntze, a mission that she will soon learn that the boat attack wasn''t a coincidence.', NULL, NULL, 3.9313, 7.449, 0, 1.06, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7122, 351339, 'tt4190530', NULL, 'Anthropoid', 'Anthropoid', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/5hUghRVVkBYufftfNQkGevY5AmE.jpg', 'https://image.tmdb.org/t/p/original/lTjRJ18JzsSfpwIdhCjv5BAMs03.jpg', 'In December 1941, Czech soldiers Jozef Gabčík and Jan Kubiš parachute into their occupied homeland to assassinate Nazi officer Reinhard Heydrich.', NULL, NULL, 5.1158, 7.131, 0, 2.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7123, 6968, 'tt0765432', NULL, 'The Baader Meinhof Complex', 'Der Baader Meinhof Komplex', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/36Y0UT6bXnkHBGmmVFWGEnEh8nI.jpg', 'https://image.tmdb.org/t/p/original/6vspNQNWrtoXQMqjsBhouCVsozG.jpg', 'When German police viciously quell a protest against the shah of Iran, popular journalist Ulrike Meinhof rebels against her dishonest marriage, walks away from her children and joins radical anarchist Andreas Baader. Together with Baader''s girlfriend, Gudrun Ensslin, they form the violent Red Faction Army, and together perpetrate a slew of terrorist attacks as a way of disrupting the fabric of what they see as an increasingly fascist state.', NULL, NULL, 3.0714, 6.965, 0, 1.08, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7124, 3482, 'tt0059825', NULL, 'The Train', 'The Train', 'movie', 1964, 'https://image.tmdb.org/t/p/w500/bzgPLB7efMohled42PIn6CcOTnO.jpg', 'https://image.tmdb.org/t/p/original/tL5uUcgmpcCZOnrnjPcNwz1LGqY.jpg', 'As the Allied forces approach Paris in August 1944, German Colonel Von Waldheim is desperate to take all of France''s greatest paintings to Germany. He manages to secure a train to transport the valuable art works even as the chaos of retreat descends upon them. The French resistance however wants to stop them from stealing their national treasures but have received orders from London that they are not to be destroyed. The station master, Labiche, is tasked with scheduling the train and making it all happen smoothly but he is also part of a dwindling group of resistance fighters tasked with preventing the theft. He and others stage an elaborate ruse to keep the train from ever leaving French territory.', NULL, NULL, 2.5102, 7.6, 0, 2.065, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7125, 789, 'tt0060802', NULL, 'Closely Watched Trains', 'Ostře sledované vlaky', 'movie', 1966, 'https://image.tmdb.org/t/p/w500/oKiOhsSRWO6fRqxtvda8WuCiXBm.jpg', 'https://image.tmdb.org/t/p/original/pe2APM7NsJXfNRfq2cUWdc0dRbQ.jpg', 'At a village railway station in occupied Czechoslovakia, a bumbling dispatcher’s apprentice longs to liberate himself from his virginity. Oblivious to the war and the resistance that surrounds him, this young man embarks on a journey of sexual awakening and self-discovery, encountering a universe of frustration, eroticism, and adventure within his sleepy backwater depot.', NULL, NULL, 2.0728, 7.224, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7126, 9065, 'tt0101829', NULL, 'Europa', 'Europa', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/pyFtuYQReoSmhNs55kRJedA5wEJ.jpg', 'https://image.tmdb.org/t/p/original/9vOfO3CP8mqqq0oqCNl9R7M07xE.jpg', 'Just after World War II, an American takes a railway job in Germany, but finds his position politically sensitive with various people trying to use him.', NULL, NULL, 2.0272, 7.344, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7127, 8883, 'tt0920458', NULL, 'Flame & Citron', 'Flammen & Citronen', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/32CKp29QyqimkjtdJRBzSRHPx4j.jpg', 'https://image.tmdb.org/t/p/original/trZRS3RfDnWBe3bQW1UUlOS210F.jpg', 'Gunman Flame and his partner Citron assassinate Nazi collaborators for the Danish resistance. Assigned targets by their Allies-connected leader, Aksel Winther, they relish the opportunity to begin targeting the Nazis themselves. When they begin to doubt the validity of their assignments, their morally complicated task becomes even more labyrinthine.', NULL, NULL, 2.0388, 6.8, 0, 1.16, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7128, 84057, 'tt1609159', NULL, 'Süskind', 'Süskind', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/gUTHRtIkXpRbQb6dCVCGnd81I5g.jpg', 'https://image.tmdb.org/t/p/original/6HrSHokojPDUS4acsGBfrhx5Whm.jpg', 'In Nazi-occupied Amsterdam, Walter Süskind is a member of the Dutch Jewish Council who rescues hundreds of children from the concentration camps.', NULL, NULL, 2.5052, 7.041, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7129, 9289, 'tt0056197', NULL, 'The Longest Day', 'The Longest Day', 'movie', 1962, 'https://image.tmdb.org/t/p/w500/5zmvEofdIlgXrQl9A7e5IOzlnFU.jpg', 'https://image.tmdb.org/t/p/original/yt9FIS2Osm97M7w4dLFkBu7YxW8.jpg', 'The retelling of June 6, 1944, from the perspectives of the Germans, US, British, Canadians, and the Free French. Marshall Erwin Rommel, touring the defenses being established as part of the Reich''s Atlantic Wall, notes to his officers that when the Allied invasion comes they must be stopped on the beach. "For the Allies as well as the Germans, it will be the longest day"', NULL, NULL, 7.9188, 7.607, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7130, 15244, 'tt0071028', NULL, 'The Written Off', 'Отписани', 'tv', 1974, 'https://image.tmdb.org/t/p/w500/2oAJirPQSNQc7lm8qX2lhLxuI5U.jpg', 'https://image.tmdb.org/t/p/original/rZZHSoUtRzwjIqJaTGwMuazieRp.jpg', '"The Written Off" is a famous Serbian TV miniseries, that was very popular in former Yugoslavia, originally airing in 1974. Due to its popularity, Radio Television of Serbia has shown reruns of the series ten times, the last re-run starting in 2012. The series has achieved something of a cult status among its audience and still attracts an estimated 3 million viewers with its last rerun. Idea of series derives from exploits of freedom fighters in Belgrade during World War II, and all the characters and events are fictitious.', NULL, NULL, 2.8352, 9.0, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7131, 86484, 'tt0074039', NULL, 'Return of the Written Off', 'Povratak otpisanih', 'tv', 1978, 'https://image.tmdb.org/t/p/w500/zgj8XT0NUKbPivcAhmR5c4T26wc.jpg', 'https://image.tmdb.org/t/p/original/l4pMjzrmiK8QzGKmEoFL8ev46Kg.jpg', 'In Summer of 1944 Prle and Tihi, young yet veteran resistance fighters, together with Joca, old and moody radio-operator, are sent by Partisans to Belgrade, the Yugoslav capital still under Nazi occupation. As victorious Partisan forces approach, Prle, Tihi and Joca must continue their underground work in order to prepare the city for liberation.', NULL, NULL, 1.2184, 7.417, 0, 2.015, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7132, 245256, 'tt31122777', NULL, 'Say Nothing', 'Say Nothing', 'tv', 2024, 'https://image.tmdb.org/t/p/w500/bAF3gTGuFNDdzGUIAnDqi5nbFf3.jpg', 'https://image.tmdb.org/t/p/original/gbeldCIJck5L0oyRkyFxHH9xAaG.jpg', 'Through the eyes of various Irish Republican Army (IRA) members, explore the extremes some people will go to in the name of their beliefs, the way a deeply divided society can suddenly tip over into armed conflict, the long shadow of radical violence for both victims and perpetrators, and the emotional and psychological costs of a code of silence.', NULL, NULL, 8.0998, 7.481, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7133, 45054, 'tt1316616', NULL, 'There Be Dragons', 'There Be Dragons', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/7y6ehxTLB1ZJl3xFVFbhcnoJx1m.jpg', 'https://image.tmdb.org/t/p/original/lCjCPWK1gPouYo92WL21fHBOtCC.jpg', 'Arising out of the horror of the Spanish Civil War, a candidate for canonization is investigated by a journalist who discovers his own estranged father had a deep, dark and devastating connection to the saint''s life.While researching the life of Josemaria Escriva, the controversial founder of Opus Dei, the young journalist Robert uncovers hidden stories of his estranged father Manolo, and is taken on a journey through the dark, terrible secrets of his family’s past.', NULL, NULL, 1.464, 5.122, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
