INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7154, 14123, 'tt0804452', NULL, 'Bratz', 'Bratz', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/nkhA8Crs7K0JHIZgSdvBeBe2QF2.jpg', 'https://image.tmdb.org/t/p/original/A1CCx5tX8owG0CMQH0fvMHpkk6m.jpg', 'The popular Bratz dolls come to life in their first live-action feature film. Finding themselves being pulled further and further apart, the fashionable four band together to fight peer pressure, learn what it means to stand up for your friends, be true to oneself and live out your dreams.', NULL, NULL, 2.3099, 5.727, 0, 1.05, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7155, 18126, 'tt1114677', NULL, 'Hannah Montana: The Movie', 'Hannah Montana: The Movie', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/nZUKhfpUCFfTy24LGBHdDlK5RLx.jpg', 'https://image.tmdb.org/t/p/original/sGqepjVCkXeG7IDPNnvpT8G3AyW.jpg', 'When Miley Stewart (aka pop-star Hannah Montana) gets too caught up in the superstar celebrity lifestyle, her dad decides it''s time for a total change of scenery. But sweet niblets! Miley must trade in all the glitz and glamour of Hollywood for some ol'' blue jeans on the family farm in Tennessee, and question if she can be both Miley Stewart and Hannah Montana.', NULL, NULL, 4.6731, 6.586, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7156, 266294, 'tt1850457', NULL, 'Sisters', 'Sisters', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/hpvHqAiusQtGNDx48dA3z5ejjon.jpg', 'https://image.tmdb.org/t/p/original/zwk2Ws5fcRYkK2lZ9k1983OPnGs.jpg', 'Two disconnected sisters are summoned to clean out their childhood bedrooms before their parents sell their family home.', NULL, NULL, 4.0495, 5.956, 0, 1.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7157, 1778, 'tt0415463', NULL, 'Zoey 101', 'Zoey 101', 'tv', 2005, 'https://image.tmdb.org/t/p/w500/3eOM57RTccTSvqcYFhWwm9DAba8.jpg', 'https://image.tmdb.org/t/p/original/92adEq7w76pC5Lry50N0PTsjJ1.jpg', 'Zoey 101 is an American television series which originally aired on Nickelodeon from January 9, 2005 until May 2, 2008. It focuses on the lives of teenager Zoey Brooks and her friends as they attend Pacific Coast Academy, a fictional boarding school in Southern California. It was created by Dan Schneider. It was initially filmed at Pepperdine University in Malibu, California, then at stages in Valencia, California beginning in season 3. It was nominated for an "Outstanding Children''s Program" Emmy in 2005. Zoey 101 was the most expensive production ever for Nickelodeon series, as it was shot completely on location in Malibu. It was also Nickelodeon''s best performance for a series premiere in almost eight years. Despite this, many critics have made negative comments about the show, its setting, and its characters.', NULL, NULL, 17.5824, 8.105, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7158, 236, 'tt0110598', NULL, 'Muriel''s Wedding', 'Muriel''s Wedding', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/zJyTr8Fo412a2OIfJGXTRAm4IwX.jpg', 'https://image.tmdb.org/t/p/original/x4sqnmV2nAKIG6cmt9WAF9xRA2M.jpg', 'Socially awkward Muriel Heslop wants nothing more than to get married. Unfortunately, due to her oppressive politician father, Muriel has never even been on a date. Ostracized by her more socially adept friends, Muriel runs into fellow outcast Rhonda Epinstalk, and the two move from their small Australian town to the big city of Sydney, where Muriel changes her name and begins the arduous task of redesigning her life to match her fantasies.', NULL, NULL, 2.749, 6.832, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7159, 511562, 'tt6237314', NULL, 'To the Beat!', 'To the Beat!', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/b5fgLrOARZ6M5FZinrfVyK35CX5.jpg', 'https://image.tmdb.org/t/p/original/pA0MLE608VdeDraaXmkfHmXDroL.jpg', 'To the Beat follows 14-year-old twins Mia and Mackie Castillo - dancers since they were toddlers. Beginning at just three years old, that''s been their one true passion. They support each other through competitions and rehearsals, even though they dance different styles. Mia loves tap and Mackie loves jazz. When their favorite pop star launches an online contest to find the most unique dance group for his next music video, the twins each form their own team to compete for the chance to dance in the video - enlisting their friends and family to help gain online votes. Meanwhile, their arch rival and neighbor, Avery, the best dancer of all (who knows it too) uses her charm and resources to get the upper hand in the competition.', NULL, NULL, 0.7622, 6.3, 0, 1.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7160, 80135, 'tt0084847', NULL, 'Valentina', 'Valentina', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/sytD27oDHLHiOXEgW733imsP23Z.jpg', 'https://image.tmdb.org/t/p/original/lMxC2jLukpxlLcHF8npwoESJM0r.jpg', 'In 1939, in a French prison camp, José Garcés of the defeated Spanish Republican army raises the spirits of his fellow prisoners by telling the story of the year he was 8 years old, 1911, in a small town in northeastern Spain. He was a rascal, baffling his father, always in trouble, and in love with Valentina, a neighbor girl. On his roof top at night he sends semaphore messages to her. He writes poems. He gets them into trouble, killing her father''s breeding pigeons. When the two families camp at a decaying castle, his tutor, a sympathetic priest, tells him about the most valiant men, the saints, the heroes, and the poets. Already a poet, he learns a lesson about being a hero.', NULL, NULL, 1.3205, 6.053, 0, 1.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7161, 10377, 'tt0104952', NULL, 'My Cousin Vinny', 'My Cousin Vinny', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/iwSURa8nS2ujwrU3s1lfxxX7voH.jpg', 'https://image.tmdb.org/t/p/original/uEoaOfvWibpvjBNxFoj4MxWn0OH.jpg', 'Two carefree pals traveling through rural Alabama on their way back to college are mistakenly arrested and charged with murder. Fortunately, one of them has a cousin who''s a lawyer - Vincent Gambini, a former auto mechanic from Brooklyn who has just passed his bar exam after his sixth try. When he arrives with his leather-clad girlfriend to try his first case, it''s a real shock - for him and the Deep South!', NULL, NULL, 6.5521, 7.499, 0, 2.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7162, 1493, 'tt0212346', NULL, 'Miss Congeniality', 'Miss Congeniality', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/pat3vKaRlB70he4ghwTMydR4TvP.jpg', 'https://image.tmdb.org/t/p/original/bTpjn4OEeoLEJYjRvEvkPfPQZdb.jpg', 'When the local FBI office receives a letter from a terrorist known only as ''The Citizen'', it''s quickly determined that he''s planning his next act at the Miss America beauty pageant. Because tough-as-nails Gracie Hart is the only female Agent at the office, she''s chosen to go undercover as the contestant from New Jersey.', NULL, NULL, 8.303, 6.53, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
