INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7186, 991, 'tt0074851', NULL, 'The Man Who Fell to Earth', 'The Man Who Fell to Earth', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/gwmPVphE5DMFFGXGMhfEFyxOOYj.jpg', 'https://image.tmdb.org/t/p/original/ew3x9p8A28p3sLE8OaHwUsb1mSQ.jpg', 'Thomas Jerome Newton is an alien who has come to Earth in search of water to save his home planet. Aided by lawyer Oliver Farnsworth, Thomas uses his knowledge of advanced technology to create profitable inventions. While developing a method to transport water, Thomas meets Mary-Lou, a quiet hotel clerk, and begins to fall in love with her. Just as he is ready to leave Earth, Thomas is intercepted by the U.S. government, and his entire plan is threatened.', NULL, NULL, 2.6831, 6.454, 0, 7.04, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
