INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7188, 10217, 'tt0120255', NULL, 'The Sweet Hereafter', 'The Sweet Hereafter', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/gJy7LMq4b5qO5fsSUSoBgm24BHf.jpg', 'https://image.tmdb.org/t/p/original/7zRAZFZ4xVMyoLEvCb4Au41uvny.jpg', 'A small mountain community in Canada is devastated when a school bus accident leaves more than a dozen of its children dead. A big-city lawyer arrives to help the survivors'' and victims'' families prepare a class-action suit, but his efforts only seem to push the townspeople further apart. At the same time, one teenage survivor of the accident has to reckon with the loss of innocence brought about by a different kind of damage.', NULL, NULL, 2.0223, 6.9, 0, 7.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
