INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7191, 4858, 'tt0427392', NULL, 'The Invasion', 'The Invasion', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/oS5rMuJXwNZZPx0ojhvjgduglD2.jpg', 'https://image.tmdb.org/t/p/original/nPpIFyRRe33xKUj3nEHZZbz364x.jpg', 'Washington, D.C. psychologist Carol Bennell and her colleague Dr. Ben Driscoll are the only two people on Earth who are aware of an epidemic running rampant through the city. They discover an alien virus aboard a crashed space shuttle that transforms anyone who comes into contact with it into unfeeling drones while they sleep. Carol realizes her son holds the key to stopping the spread of the plague and she races to find him before it is too late.', NULL, NULL, 8.2961, 6.054, 0, 6.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
