INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7196, 297680, 'tt3245656', NULL, 'Hangar 10', 'Hangar 10', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/9ios4yceUMuYtiUIetd3Fhbpk4X.jpg', 'https://image.tmdb.org/t/p/original/gzVBOjjLxhR4e0dzBFbZIhg14cN.jpg', '33 years after the infamous Rendlesham Forest UFO incident, three metal detector enthusiasts hunting for Saxon gold in the same region, capture incredible footage of UFO''s whilst filming their expedition. As night falls and with their navigation equipment failing, they find themselves facing a terrifying encounter with an unforgiving alien presence.', NULL, NULL, 0.8908, 4.102, 0, 7.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7197, 689703, 'tt17079602', NULL, 'The Alien Report', 'The Alien Report', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/hrkcGA0JqE8gm1yqO6xLSAd3lGS.jpg', 'https://image.tmdb.org/t/p/original/faRFAlMWiGwIzVHAlNw5dsnAlFH.jpg', 'A life-long alien abductee figures out a clever way to record his alien encounters using a micro camera, and shares high-res video of telepathic beings, human hybrids and more.', NULL, NULL, 0.9135, 0.0, 0, 7.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7198, 169219, 'tt1905040', NULL, 'The Dyatlov Pass Incident', 'The Dyatlov Pass Incident', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/8hyvniwVeSvKbTNKrY44ndMsQht.jpg', 'https://image.tmdb.org/t/p/original/j5iUZRZtaPJbYJxvB6ZtmbE5LsZ.jpg', 'In February of 1959, nine Russian hikers ventured into a remote area of the Ural Mountains. Two weeks later, all of them were found dead. What happened is a mystery that has baffled investigators and researchers for decades. It has become known as the Dyatlov Pass Incident.  When five ambitious American college students are issued a grant to return to the site of the original events, they gear up with the belief that they can uncover and document the truth of what happened to the supposedly experienced hikers. But what they find is more shocking than anything they could have imagined. Retracing the steps of the Russians'' ill-fated journey, the students are plagued by strange and increasingly terrifying phenomena that suggest that in spite of the desolate surroundings, they are not alone. The forces at work in the Dyatlov Pass Incident have been waiting for them.', NULL, NULL, 2.5765, 5.95, 0, 8.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7199, 419825, 'tt9036998', NULL, 'The Phoenix Tapes ''97', 'The Phoenix Tapes ''97', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/pcBro07U8hARvconcYHJAQGz50J.jpg', 'https://image.tmdb.org/t/p/original/1C4E4r0OmRIHWLhK3CLPvFZZ5Ps.jpg', 'In 1997, four campers went missing during the Phoenix Lights incident and their bodies were never found. The Phoenix Tapes 97 is comprised of their final footage. This film is dedicated to the lives lost during the events displayed. To their families and friends and to the authorities who continue to search for answers. ​ The tapes were found by Dustin Miller''s father two years after Dustin was mysteriously shot and killed at a traffic stop in Texas. Peter Miller believes his son was acting as a whistleblower and had smuggled the tapes from his classified government agency in an effort to expose the truth as to what really happened to the four missing campers seen in the tapes. ​ After searching every newspaper and media publication around Phoenix during that time period, we only found one initial announcement that four campers were reported missing, as well as a formal police report folder with local PD but the folder had no files inside.', NULL, NULL, 1.2088, 6.602, 0, 7.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7200, 43275, 'tt0111021', NULL, 'Roswell', 'Roswell', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/kU1WrVsRYG8d6qyMhEsRk5dvT5z.jpg', 'https://image.tmdb.org/t/p/original/fT4eXXGflcGhqCm4ie62DXtj0rF.jpg', 'Based on the book "UFO Crash at Roswell" by Kevin Randle and Donald Schmitt, Roswell follows the attempts of Major Jesse Marcel to discover the truth about strange debris found on a local rancher''s field in July of 1947. Told by his superiors that what he has found is nothing more than a downed weather balloon, Marcel maintains his military duty until the weight of the truth, however out of this world it may be, forces him to piece together what really occurred.', NULL, NULL, 1.2767, 6.089, 0, 8.07, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
