INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7272, 78363, 'tt1896788', NULL, 'My Little Princess', 'My Little Princess', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/uHBBHx7AXfk3tNhy3zYgF8DttYm.jpg', 'https://image.tmdb.org/t/p/original/89MfnOg6pQbPPy70a5J5yhtrtIH.jpg', 'Young Violetta and her mother Hannah are a peculiar couple. Ten-year-old Violetta lives a quiet life with her grandmother, while her mother Hannah is an unpredictable photographer who lives off of the generosity of others. When Hannah forces her daughter to pose as a model, Violetta finds her life with her loving grandmother turned upside down.The resulting pictures quickly become a sensation for the trendy 70''s Paris art scene, and Violetta finds herself caught in between her new stature as an art muse and her dull childhood.', NULL, NULL, 1.6627, 6.5, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
