INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7276, 44018, 'tt0089960', NULL, 'Vagabond', 'Sans toit ni loi', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/2KFfwiPct1hwqi9dkKqoom0BenC.jpg', 'https://image.tmdb.org/t/p/original/tKsFh8qpYyi2AMg5O8QTVdChm4k.jpg', 'Mona Bergeron is dead, her frozen body found in a ditch in the French countryside. From this, the film flashes back to the weeks leading up to her death. Through these flashbacks, Mona gradually declines as she travels from place to place, taking odd jobs and staying with whomever will offer her a place to sleep. Mona is fiercely independent, craving freedom over comfort, but it is this desire to be free that will eventually lead to her demise.', NULL, NULL, 1.6813, 7.35, 0, 2.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7277, NULL, NULL, 62151, 'Life Is Strange 2', 'Life Is Strange 2', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7p.jpg', NULL, 'Life Is Strange 2 is an episodic adventure game played from a third-person perspective. Players control Sean Diaz, a teenager on the run with his younger brother Daniel after a tragic incident forces them to flee their home in Seattle. The game uses a road trip structure inspired by films like Into the Wild and Stand By Me, with each episode set in a new location along the US West Coast. Sean must make choices that affect both the story''s branching paths and Daniel''s developing morality and behavior. The game explores themes of family, brotherhood, and contemporary social issues through its narrative-driven gameplay.', 'https://www.igdb.com/games/life-is-strange-2', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7278, 238603, 'tt2183034', NULL, 'Earth to Echo', 'Earth to Echo', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/yiNPza51nLvVTWTB9q4ifzfUlml.jpg', 'https://image.tmdb.org/t/p/original/xqCU96foxW8w2dhaEhP3vr1Sx4R.jpg', 'After a construction project begins digging in their neighbourhood, best friends Tuck, Munch and Alex inexplicably begin to receive strange, encoded messages on their cell phones. Convinced something bigger is going on, they go to their parents and the authorities. The three embark on a secret adventure to crack the code and follow it to its source, and discover a mysterious being from another world who desperately needs their help. The journey that follows will change all their lives forever.', NULL, NULL, 3.64, 5.895, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
