INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7280, 121572, 'tt2076372', NULL, 'Toad Road', 'Toad Road', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/71uFW8n72RuRjsrGfFgJDhutcV5.jpg', 'https://image.tmdb.org/t/p/original/93J92SYSiJpl1XRRNXDwZ3p7Xps.jpg', 'Stuck in a dead end town, young James kills time with his druggie friends, engaging in debauched chemical intake to the point of unconsciousness, until he meets Sara, a sweet new arrival to their group. However, Sara wants James to take her further into the world of narcotics experimentation (just as James was contemplating abandoning this lifestyle), and she also wants him to introduce her to the sinister local legend of Toad Road, a spot deep in the forest that is apparently home to the Seven Gates of Hell.', NULL, NULL, 0.4243, 4.77, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
