INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7338, 1567187, 'tt33052885', NULL, 'A Mother''s Recall', 'Memoria de una madre', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/vhfrAIIe9jHiuD9qjOhLwnEgLdb.jpg', 'https://image.tmdb.org/t/p/original/v2SOWxOgifIhnZFLgIEvzr7ZbJ2.jpg', 'A married couple welcomes young Genaro into their home through adoption. Upon his arrival, he meets his new siblings, Nuria and Samuel. But it doesn''t take long for Genaro to sense that something is deeply wrong within the household. The family seems trapped under a suffocating veil of fear and despair, haunted by an unseen force. As Nuria, a troubled teenager, begins to uncover the terrifying secrets hidden within her family, she forms a powerful bond with Genaro. Together, they must face an evil presence that grows stronger each day, unleashing a chain of sinister and unsettling events.', NULL, NULL, 49.6735, 0.0, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7339, 1113682, 'tt3984388', NULL, 'Close Up', 'Close Up', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/76Wud5jsFJDMpBoRVzwluMZeaa.jpg', NULL, 'More than 150 silent short films about singers, actors and directors captured during Press Conferences in Cannes, Venice and Berlin, between 1993 and 2002. Presented the first time in 2012 (ten years after the last shooting) in Napoli Film Festival and in 2013 at the Art Institute of California in Santa Ana. An anthropological experiment on the facial expressions of famous people showing the human being aspect. All original footage from Mel Gibson to Peter Jackson, from George Lucas to Catherine Deneuve, from Michael Douglas to Giancarlo Giannini and many others.', NULL, NULL, 1.2823, 9.5, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
