INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7358, 34288, 'tt0122143', NULL, 'The Last Broadcast', 'The Last Broadcast', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/wexVSBnfx4fggSmLxzn1kc51Q5.jpg', 'https://image.tmdb.org/t/p/original/8ex3KmRxQSPG3ap2FVjfU6zQQdQ.jpg', 'In December 1995, a four-man team from the public-access program, "Fact or Fiction", braved the New Jersey''s desolate Pine Barrens determined to deliver a live broadcast of the legendary Jersey Devil. Only one came out alive. It took the jury ninety minutes to sentence the lone survivor to life in prison. One year later, a filmmaker decides to mount his own investigation...', NULL, NULL, 0.8631, 5.004, 0, 1.11, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7359, 1155067, 'tt28346692', NULL, 'Transmission', 'Transmission', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/ifOdVvtzrpH5MKdFj6Ydt6G8FnC.jpg', 'https://image.tmdb.org/t/p/original/hXHrfihU5Ysa8ljVkpwbp7S7cuT.jpg', 'The world''s first channel-surfing horror film, unfolding on a television screen as we switch between different channels and slowly realise that each of these channels is actually telling different aspects of the same horrific narrative.', NULL, NULL, 1.4713, 4.1, 0, 1.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7360, 123105, 'tt1713476', NULL, 'The Bay', 'The Bay', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/fnmYgr4AOOE09zKa7omPW1FWT8K.jpg', 'https://image.tmdb.org/t/p/original/qCaDSX1UjgWRGeh5Cmj9SAUbS1L.jpg', 'Two million fish washed ashore. One thousand blackbirds dropped from the sky. On July 4, 2009 a deadly menace swept through the quaint seaside town of Claridge, Maryland, but the harrowing story of what happened that Independence Day has never been told—until now. The authorities believed they had buried the truth about the tragedy that claimed over 700 human lives. Now, three years later, a reporter has emerged with footage revealing the cover-up and an unimaginable killer: a mysterious parasitic outbreak. Told from the perspective of those who were there and saw what happened, The Bay unfolds over 24 hours through people''s iPhones, Androids, 911 calls, webcams, and whatever else could be used to document the nightmare in Claridge. What follows is a nerve-shredding tale of a small town plunged into absolute terror.', NULL, NULL, 2.871, 5.804, 0, 2.025, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
