INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7368, 211067, 'tt2383068', NULL, 'The Sacrament', 'The Sacrament', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/thdioQOYqqusDUfT6trgwMIoNaQ.jpg', 'https://image.tmdb.org/t/p/original/vNKlrvHiw32yrjnUoaTMGnH6soN.jpg', 'Two journalists set out to document their friend''s journey to reunite with his estranged sister. They track her to an undisclosed location where they are welcomed into the remote world of "Eden Parish," a self-sustained rural utopia composed of nearly two hundred members and overseen by a mysterious leader known only as "Father." It quickly becomes evident to the newcomers that this paradise may not be as it seems. Eden Parish harbors a twisted secret. What started as just another documentary shoot soon becomes a fight for survival.', NULL, NULL, 1.8114, 5.959, 0, 1.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
