INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7370, 505058, 'tt4761916', NULL, 'Unfriended: Dark Web', 'Unfriended: Dark Web', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/nOXuOeD07nZPT29IgiGT0S8PZH.jpg', 'https://image.tmdb.org/t/p/original/2Dk9WG8R0PYlgZjo5F9iheKybpO.jpg', '​When a 20-something finds a cache of hidden files on his new laptop, he and his friends are unwittingly thrust into the depths of the dark web. They soon discover someone has been watching their every move and will go to unimaginable lengths to protect the dark web.', NULL, NULL, 4.2611, 6.286, 0, 11.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7371, 49950, 'tt1265990', NULL, 'The Roommate', 'The Roommate', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/kQZcOn5rDuwpbQTluC4Wm0amYmR.jpg', 'https://image.tmdb.org/t/p/original/501U1FiY8ylubAlDbz6UcTHxvfA.jpg', 'When Sara, a young design student from Iowa, arrives for college in Los Angeles, she is eager to fit in and get to know the big city. Her wealthy roommate, Rebecca, is more than eager to take Sara under her wing and show her the ropes. The two become close, but when Sara begins to branch out and make more friends on campus, Rebecca becomes resentful. Alarmed, Sara moves in with her new boyfriend, causing Rebecca''s behavior to take a violent turn.', NULL, NULL, 3.8167, 5.4, 0, 10.01, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
