INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7402, 82532, 'tt1588334', NULL, 'Jeff, Who Lives at Home', 'Jeff, Who Lives at Home', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/9zn7I5dmZ7IGng87gWVk9K37eq7.jpg', 'https://image.tmdb.org/t/p/original/2TlVQC5s6veC9MZSIj9K2Drrb.jpg', 'Dispatched from his basement room on an errand for his mother, slacker Jeff might discover his destiny (finally) when he spends the day with his brother as he tracks his possibly adulterous wife.', NULL, NULL, 2.0315, 6.22, 0, 11.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7403, 9788, 'tt0384793', NULL, 'Accepted', 'Accepted', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/pMh1dCw5vhMATmJs0ve0OpoSVED.jpg', 'https://image.tmdb.org/t/p/original/oDwOULlopGrBX282RRQlDcGXhGV.jpg', 'A high school slacker who''s rejected by every school he applies to opts to create his own institution of higher learning, the South Harmon Institute of Technology, on a rundown piece of property near his hometown.', NULL, NULL, 4.7483, 6.5, 0, 11.03, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7404, 83446, 'tt0079619', NULL, 'Oblomov', 'Несколько дней из жизни И.И. Обломова', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/ero51WWvP9UJXPMnH3DyZLjIofR.jpg', 'https://image.tmdb.org/t/p/original/gwRS8rZMGLMhjauNZpoHJ9FI8Zt.jpg', 'St. Petersburg, mid 19th century: the indolent, middle-aged Oblomov lives in a flat with his older servant, Zakhar. He sleeps much of the day, dreaming of his childhood on his parents'' estate. His boyhood companion, Stoltz, now an energetic and successful businessman, adds Oblomov to his circle whenever he''s in the city, and Oblomov''s life changes when Stoltz introduces him to Olga, lovely and cultured. When Stoltz leaves for several months, Oblomov takes a country house near Olga''s, and she determines to change him: to turn him into a man of society, action, and culture. Soon, Olga and Oblomov are in love; but where, in the triangle, does that leave Stoltz?', NULL, NULL, 1.2757, 6.298, 0, 11.02, '2026-08-04 03:20:13', '2026-08-04 03:20:13');
