UPDATE "recommendations" SET "tmdb_id"=11905, "imdb_id"='tt0087075', "igdb_id"=NULL, "title"='The Company of Wolves', "original_title"='The Company of Wolves', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/2g2YPws1MiEWTodUE8u3qOf78XS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8LMKwSUdHxU8AGPVY7BV4wS5TeQ.jpg', "overview"='An adaptation of Angela Carter''s fairy tales. Young Rosaleen dreams of a village in the dark woods, where Granny tells her cautionary tales in which innocent maidens are tempted by wolves who are hairy on the inside. As Rosaleen grows into womanhood, will the wolves come for her too?', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6119, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=1.59383333333333325e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=20;
UPDATE "recommendations" SET "tmdb_id"=179111, "imdb_id"='tt2375574', "igdb_id"=NULL, "title"='A Field in England', "original_title"='A Field in England', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/dKhMJr8yoHVyvxyUiAeIn2hKVdL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/euBvKWkvYD38O7dMMvw3GvrkZoa.jpg', "overview"='During the Civil War in 17th-Century England, a small group of deserters flee from a raging battle through an overgrown field. They are captured by an alchemist, who forces the group to aid him in his search to find a hidden treasure that he believes is buried in the field. Crossing a vast mushroom circle, which provides their first meal, the group quickly descend into a chaos of arguments, fighting and paranoia, and, as it becomes clear that the treasure might be something other than gold, they slowly become victim to the terrifying energies trapped inside the field.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.193, "vote_average"=6.212, "is_ambiguous"=0, "evidence_score"=11.675, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=21;
UPDATE "recommendations" SET "tmdb_id"=10957, "imdb_id"='tt0088814', "igdb_id"=NULL, "title"='The Black Cauldron', "original_title"='The Black Cauldron', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/h64i9e6oJs2jrDZ4QzspXMqZhPF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4idEU92m0oR1BWa1iwb5pZ9bWCu.jpg', "overview"='Taran is an assistant pigkeeper with boyish dreams of becoming a great warrior. However, he has to put the daydreaming aside when his charge, an oracular pig named Hen Wen, is kidnapped by an evil lord known as the Horned King. The villain hopes Hen will show him the way to The Black Cauldron, which has the power to create a giant army of unstoppable soldiers.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2452, "vote_average"=6.441, "is_ambiguous"=0, "evidence_score"=1.47540000000000013e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=22;
UPDATE "recommendations" SET "tmdb_id"=13597, "imdb_id"='tt0091369', "igdb_id"=NULL, "title"='Labyrinth', "original_title"='Labyrinth', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mGkleIuPO2flRyvP8yBcUykSQsp.jpg', "overview"='Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6038, "vote_average"=7.289, "is_ambiguous"=0, "evidence_score"=26.735, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=23;
