UPDATE "recommendations" SET "tmdb_id"=73499, "imdb_id"='tt1646980', "igdb_id"=NULL, "title"='The Double', "original_title"='The Double', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/t4W10sjJSDAWRUDn2Kb8DQKxiZv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tY1z1IqNBTiH4bUXt4LLiYXLYpq.jpg', "overview"='The mysterious murder of a US senator bearing the distinctive trademark of the legendary Soviet assassin ''Cassius'', forces retired CIA operative, Paul Shepherson to team with rookie FBI agent, Ben Geary  to solve the crime. Having spent his career chasing Cassius, Shepherdson is convinced his nemesis is long dead, but is pushed to take on the case by his former supervisor, Tom Highland. Geary, who wrote his Master''s thesis on Shepherdson''s pursuit of the Soviet killer, is certain that Cassius has resurfaced.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4336, "vote_average"=5.8, "is_ambiguous"=0, "evidence_score"=10.765, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=108;
