UPDATE "recommendations" SET "tmdb_id"=9323, "imdb_id"='tt0113568', "igdb_id"=NULL, "title"='Ghost in the Shell', "original_title"='GHOST IN THE SHELL', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gTRXgigmgKpeJjW07iq686HZyBD.jpg', "overview"='In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as ''The Puppetmaster'' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.5014, "vote_average"=7.925, "is_ambiguous"=0, "evidence_score"=31.1532, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=538;
