UPDATE "recommendations" SET "tmdb_id"=198184, "imdb_id"='tt1823672', "igdb_id"=NULL, "title"='Chappie', "original_title"='Chappie', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3pKIcv6KhUE35jsKnv3MylQ3OT2.jpg', "overview"='Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there''s one thing that makes Chappie different from any one else: he is a robot.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.7447, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=12.14, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=543;
