UPDATE "recommendations" SET "tmdb_id"=277, "imdb_id"='tt0320691', "igdb_id"=NULL, "title"='Underworld', "original_title"='Underworld', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/zsnQ41UZ3jo1wEeemF0eA9cAIU0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zsgdVbuEwqZbnUN9qLGEMBYf2Zo.jpg', "overview"='Vampires and werewolves have waged a nocturnal war against each other for centuries. But all bets are off when a female vampire warrior named Selene, who''s famous for her strength and werewolf-hunting prowess, becomes smitten with a peace-loving male werewolf, Michael, who wants to end the war.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3444, "vote_average"=6.857, "is_ambiguous"=0, "evidence_score"=3.17270833333333328e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=562;
UPDATE "recommendations" SET "tmdb_id"=30959, "imdb_id"='tt0058279', "igdb_id"=NULL, "title"='Kwaidan', "original_title"='怪談', "media_type"='movie', "release_year"=1965, "poster_url"='https://image.tmdb.org/t/p/w500/t9UMfViYl47SdZZatKQ1JKjjCgs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9GAU0z2wVA8M2D2w36CaloWYYgv.jpg', "overview"='Taking its title from an archaic Japanese word meaning "ghost story," this anthology adapts four folk tales. A penniless samurai marries for money with tragic results. A man stranded in a blizzard is saved by Yuki the Snow Maiden, but his rescue comes at a cost. Blind musician Hoichi is forced to perform for an audience of ghosts. An author relates the story of a samurai who sees another warrior''s reflection in his teacup.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5262, "vote_average"=7.722, "is_ambiguous"=0, "evidence_score"=1.86509090909090886e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=565;
UPDATE "recommendations" SET "tmdb_id"=565, "imdb_id"='tt0298130', "igdb_id"=NULL, "title"='The Ring', "original_title"='The Ring', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/AeRpUynJKDpJveklBJipOYrVxCS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6tuNQ16hC4Qp7wjTweKzUnnLBkI.jpg', "overview"='Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.1533, "vote_average"=6.708, "is_ambiguous"=0, "evidence_score"=2.70636363636363626e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=574;
UPDATE "recommendations" SET "tmdb_id"=3763, "imdb_id"='tt0058430', "igdb_id"=NULL, "title"='Onibaba', "original_title"='鬼婆', "media_type"='movie', "release_year"=1964, "poster_url"='https://image.tmdb.org/t/p/w500/xyPLG53OodhJtvfQEfcmC43l16O.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AcAMkNfQ21cL7EJzs5eVx24k3H4.jpg', "overview"='While her son, Kichi, is away at war, a woman and her daughter-in-law survive by killing samurai who stray into their swamp, then selling whatever valuables they find. Both are devastated when they learn that Kichi has died, but his wife soon begins an affair with a neighbor who survived the war, Hachi. The mother disapproves and, when she can''t steal Hachi for herself, tries to scare her daughter-in-law with a mysterious mask from a dead samurai.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.8482, "vote_average"=7.675, "is_ambiguous"=0, "evidence_score"=12.26, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=575;
