UPDATE "recommendations" SET "tmdb_id"=1878, "imdb_id"='tt0120669', "igdb_id"=NULL, "title"='Fear and Loathing in Las Vegas', "original_title"='Fear and Loathing in Las Vegas', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/tisNLcMkxryU2zxhi0PiyDFqhm0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qJaR9AZx2Qq2oJ3krnSO0Z5ne5I.jpg', "overview"='Raoul Duke and his attorney Dr. Gonzo drive a red convertible across the Mojave desert to Las Vegas with a suitcase full of drugs to cover a motorcycle race. As their consumption of drugs increases at an alarming rate, the stoned duo trash their hotel room and fear legal repercussions. Duke begins to drive back to L.A., but after an odd run-in with a cop, he returns to Sin City and continues his wild drug binge.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4276, "vote_average"=7.2, "is_ambiguous"=0, "evidence_score"=25.5325, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=600;
