UPDATE "recommendations" SET "tmdb_id"=82507, "imdb_id"='tt1922777', "igdb_id"=NULL, "title"='Sinister', "original_title"='Sinister', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jovIEk4cAxWmA2dBcPrfhn3jzYN.jpg', "overview"='True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.8983, "vote_average"=6.876, "is_ambiguous"=0, "evidence_score"=20.139375, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=791;
UPDATE "recommendations" SET "tmdb_id"=9479, "imdb_id"='tt0107688', "igdb_id"=NULL, "title"='The Nightmare Before Christmas', "original_title"='The Nightmare Before Christmas', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', "overview"='Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.3684, "vote_average"=7.834, "is_ambiguous"=0, "evidence_score"=1.28085714285714296e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=801;
