UPDATE "recommendations" SET "tmdb_id"=1408208, "imdb_id"='tt35222590', "igdb_id"=NULL, "title"='Exit 8', "original_title"='８番出口', "media_type"='movie', "release_year"=2025, "poster_url"='https://image.tmdb.org/t/p/w500/nQXYTvm6AY4WmtcPskroqC7Skh.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/f5csnjqQj5qdqc0EZchon94hXZ6.jpg', "overview"='A man trapped in an endless sterile subway passageway sets out to find Exit 8. The rules of his quest are simple: do not overlook anything out of the ordinary. If you discover an anomaly, turn back immediately. If you don’t, carry on. Then leave from Exit 8. But even a single oversight will send him back to the beginning. Will he ever reach his goal and escape this infinite corridor?', "external_url"=NULL, "platforms"=NULL, "popularity"=13.4809, "vote_average"=7.002, "is_ambiguous"=0, "evidence_score"=6.00666666666666682e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=1275;
