UPDATE "recommendations" SET "tmdb_id"=3558, "imdb_id"='tt0172493', "igdb_id"=NULL, "title"='Girl, Interrupted', "original_title"='Girl, Interrupted', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/dOBdatHIVppvmRFw2z7bf9VKJr9.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jDePFWhpfkY4GJm41qiRffJ0NGq.jpg', "overview"='Set in the changing world of the late 1960s, Susanna Kaysen''s prescribed "short rest" from a psychiatrist she had met only once becomes a strange, unknown journey into Alice''s Wonderland, where she struggles with the thin line between normal and crazy. Susanna soon realizes how hard it is to get out once she has been committed, and she ultimately has to choose between the world of people who belong inside or the difficult world of reality outside.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.4341, "vote_average"=7.562, "is_ambiguous"=0, "evidence_score"=2.48740000000000023e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=1448;
