UPDATE "recommendations" SET "tmdb_id"=95, "imdb_id"='tt0120591', "igdb_id"=NULL, "title"='Armageddon', "original_title"='Armageddon', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/eTM3qtGhDU8cvjpoa6KEt5E2auU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1cO6OQJxz7YhTZ4V1OlkYfebeJa.jpg', "overview"='When an asteroid threatens to collide with Earth, NASA honcho Dan Truman determines the only way to stop it is to drill into its surface and detonate a nuclear bomb. This leads him to renowned driller Harry Stamper, who agrees to helm the dangerous space mission provided he can bring along his own hotshot crew. Among them is the cocksure A.J. who Harry thinks isn''t good enough for his daughter, until the mission proves otherwise.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.0985, "vote_average"=6.834, "is_ambiguous"=0, "evidence_score"=9.0125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=1476;
UPDATE "recommendations" SET "tmdb_id"=6282, "imdb_id"='tt0200550', "igdb_id"=NULL, "title"='Coyote Ugly', "original_title"='Coyote Ugly', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/xYM0laKrEqjiRSQNvqRrXPXN3iL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/f2MzXz3vjuNtSPn17ugFa6oTUmc.jpg', "overview"='Graced with a velvet voice, 21-year-old Violet Sanford heads to New York to pursue her dream of becoming a songwriter only to find her aspirations sidelined by the accolades and notoriety she receives at her "day" job as a barmaid at Coyote Ugly. The "Coyotes" as they are affectionately called tantalize customers and the media alike with their outrageous antics, making Coyote Ugly the watering hole for guys on the prowl.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.3036, "vote_average"=6.257, "is_ambiguous"=0, "evidence_score"=1.4084999999999999e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=1480;
