UPDATE "recommendations" SET "tmdb_id"=82094, "imdb_id"='tt0174834', "igdb_id"=NULL, "title"='The Pied Piper', "original_title"='Krysař', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/tYDRQvqgTUorU37ZzEFULNMvMHf.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cY3sSQRZZc7olOMYHVqeYAEGRvd.jpg', "overview"='A darkly brilliant stop-motion adaptation of The Pied Piper of Hamelin about a plague of rats that punish townsfolk corrupt with greed.  One of the most ambitious Czech animation projects of the 1980s, notable for its unusual dark art direction, innovative animation techniques and use of a fictitious language.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.7768, "vote_average"=7.45, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-04 03:20:13' WHERE "id"=2246;
