UPDATE "recommendations" SET "tmdb_id"=293572, "imdb_id"='tt1958043', "igdb_id"=NULL, "title"='The Houses October Built', "original_title"='The Houses October Built', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/yGTHvZE1ggog8w06kqg1HyTANjT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lCyR4kEM5rVpKBdq4lgMIrKl5Ro.jpg', "overview"='Beneath the fake blood and cheap masks of countless haunted house attractions across the country, there are whispers of truly terrifying alternatives. Looking to find an authentic, blood-curdling good fright for Halloween, five friends set off on a road trip in an RV to track down these underground Haunts. Just when their search seems to reach a dead end, strange and disturbing things start happening and it becomes clear that the Haunt has come to them…', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2533, "vote_average"=5.0, "is_ambiguous"=0, "evidence_score"=6.625, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-04 03:20:13' WHERE "id"=3110;
