UPDATE "recommendations" SET "tmdb_id"=14334, "imdb_id"='tt0111112', "igdb_id"=NULL, "title"='The Secret of Roan Inish', "original_title"='The Secret of Roan Inish', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/2FFcEEMMrnXh3CFz3aON92sLkXP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4kdjUgayHYUgsQlr2TsMzDHC2At.jpg', "overview"='Ten-year-old Fiona is sent to live with her grandparents in a small fishing village in Donegal, Ireland. She soon learns the local legend that an ancestor of hers married a Selkie – a seal who can turn into a human. Years earlier, her baby brother was washed out to sea and never seen again, so when Fiona spies a naked little boy on the abandoned Isle of Roan Inish, she is compelled to investigate.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.792, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=7.0771428571428574e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-04 03:20:13' WHERE "id"=3167;
