UPDATE "recommendations" SET "tmdb_id"=10276, "imdb_id"='tt0103241', "igdb_id"=NULL, "title"='What About Bob?', "original_title"='What About Bob?', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/pFCrGGGhV5xeAdvEysv6aSv8T13.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2Ek1JtggvRquMfzie66ybbID9g0.jpg', "overview"='Before going on vacation, self-involved psychiatrist Dr. Leo Marvin has the misfortune of taking on a new patient: Bob Wiley. An exemplar of neediness and a compendium of phobias, Bob follows Marvin to his family''s country house. Dr. Marvin tries to get him to leave; the trouble is, everyone loves Bob. As his oblivious patient makes himself at home, Dr. Marvin loses his professional composure and, before long, may be ready for the loony bin himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6616, "vote_average"=6.9, "is_ambiguous"=0, "evidence_score"=1.01655555555555547e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-04 03:20:13' WHERE "id"=3482;
