UPDATE "recommendations" SET "tmdb_id"=102651, "imdb_id"='tt1587310', "igdb_id"=NULL, "title"='Maleficent', "original_title"='Maleficent', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/ik8PugpL41s137RAWEGTAWu0dPo.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bNiiUCQUD7ij5Ybh2GoWSZwqAb1.jpg', "overview"='A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land. She rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent''s true happiness as well.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.5323, "vote_average"=7.088, "is_ambiguous"=0, "evidence_score"=8.615, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-04 03:20:13' WHERE "id"=5674;
