UPDATE "recommendations" SET "tmdb_id"=11655, "imdb_id"='tt0104029', "igdb_id"=NULL, "title"='Cronos', "original_title"='Cronos', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/tQqIA8bDN7v1LmHjJg7Qh9BKCLa.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nR16suoZalsNzJvtkN8nxsTVwrR.jpg', "overview"='Faced with his own mortality, an ingenious alchemist tried to perfect an invention that would provide him with the key to eternal life. It was called the Cronos device. When he died more than 400 years later, he took the secrets of this remarkable device to the grave with him. Now, an elderly antiques dealer has found the hellish machine hidden in a statue and learns about its incredible powers. The more he uses the device, the younger he becomes...but nothing comes without a price. Life after death is just the beginning as this nerve-shattering thriller unfolds and the fountain of youth turns bloody.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5658, "vote_average"=6.678, "is_ambiguous"=0, "evidence_score"=9.01, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-04 03:20:13' WHERE "id"=6330;
