UPDATE "recommendations" SET "tmdb_id"=11513, "imdb_id"='tt0094888', "igdb_id"=NULL, "title"='Cobra Verde', "original_title"='Cobra Verde', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/5Cce5ZgJ9yyDqCmwAi6mcULfIop.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uHwJaXKtIsjI4IrtaFLnJjLZMrs.jpg', "overview"='A fearsome 19th century bandit, Cobra Verde cuts a swath through Brazil until he arrives at the sugar plantation of Don Octávio Countinho. Not knowing that his new guest is the notorious bandit and impressed by his ruthless ways, Don Octávio hires Cobra Verde to oversee his slaves. But when Cobra Verde impregnates Don Octávio’s three daughters, the incensed plantation owner exiles the outlaw to Africa where he is expected to reopen the slave trade. Following his trans-Atlantic journey, Cobra Verde exploits tribal conflicts to commandeer an abandoned fortress and whips an army of naked warriors into a frenzied bloodlust as he vies for survival.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.8948, "vote_average"=6.898, "is_ambiguous"=0, "evidence_score"=6.27999999999999936e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-04 03:20:13' WHERE "id"=6354;
