UPDATE "recommendations" SET "tmdb_id"=4584, "imdb_id"='tt0114388', "igdb_id"=NULL, "title"='Sense and Sensibility', "original_title"='Sense and Sensibility', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/9YdQ73YmvInxpXZVNjEKePw9tRO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cFnyfWHL6HjOOVal6lp8e5gqibK.jpg', "overview"='The Dashwood sisters, sensible Elinor and passionate Marianne, learn that their prospects of marriage seem doomed by their family''s sudden loss of fortune. After Henry Dashwood dies unexpectedly, his estate must pass on by law to his son. These circumstances leave Mr. Dashwood''s wife and daughters without a home and with barely enough money to live on. As Elinor and Marianne struggle to find romantic fulfillment in a society obsessed with financial and social status, they must learn to mix sense with sensibility in their dealings with both money and men.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.1702, "vote_average"=7.425, "is_ambiguous"=0, "evidence_score"=5.014, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-04 03:20:13' WHERE "id"=6382;
